function profileFor(b){const extra=references[b.id]||{},ma=metalArchives[b.id]||{},base=profiles[b.id]||{},raw={...extra,...base,members:base.members?.length?base.members:extra.members?.length?extra.members:ma.members,members_source:base.members_source||extra.members_source||ma.source_url,albums:extra.albums},review=raw.reviewed||{};const age=Date.now()-new Date(review.members_checked_at||0).getTime();if(review.members_checked_at&&age>30*86400000)return {...raw,members_note:(raw.members_note||'')+' Ручная проверка состава устарела; показаны сведения справочника.'};return {...raw,...review};}
function upcomingEvents(p,now=new Date()){const today=now.toLocaleDateString('sv-SE',{timeZone:'Asia/Novosibirsk'});return (p.events||[]).filter(e=>/^\d{4}-\d{2}-\d{2}$/.test(e.date)&&e.city&&e.date>=today).sort((a,b)=>a.date.localeCompare(b.date));}
function sourceLabel(url){try{return new URL(url).hostname.replace(/^www\./,'');}catch(e){return 'Источник';}}
function source(parent,url,label){if(!/^https?:\/\//i.test(url||''))return;const a=node('a',label||sourceLabel(url),'source');a.href=url;a.target='_blank';a.rel='noopener';parent.append(a);}
function checked(parent,value){if(value){const d=new Date(value);if(!Number.isNaN(d.getTime()))parent.append(node('p','Проверено: '+d.toLocaleDateString('ru-RU'),'muted'));}}
function eventDate(e){return new Date(e.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});}
function eventCard(e){const card=node('div',undefined,'card');card.append(node('div',eventDate(e),'muted'),node('h2',[e.city,e.country].filter(Boolean).join(' · ')),node('p',e.venue||''));source(card,e.source_url,'Афиша / источник ↗');return card;}
function renderProfile(){const holder=$('bandInfo');holder.classList.remove('hidden');holder.replaceChildren();if(detail){renderDetail(holder);return;}const raw=profileFor(band),ma=metalArchives[band.id]||{},facts=music[band.id]?.data||{},p={...raw,origin:raw.origin||facts.origin,genres:raw.genres||facts.genres,website:raw.website||facts.website},events=upcomingEvents(p);
if(['members','albums','setlists'].includes(bandSection)){renderMusicSection(holder,p);return;}
if(bandSection==='tour'){holder.append(node('h2','Предстоящие концерты'));if(!events.length)holder.append(node('p','В нашей базе пока нет подтверждённых будущих дат. Это не означает, что группа не выступает.','muted'));for(const e of events)holder.append(eventCard(e));checked(holder,p.tour_checked_at);source(holder,p.tour_source||p.website,'Расписание на сайте группы ↗');return;}
if(bandSection==='where'){holder.append(node('h2','Где выступают'));const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Novosibirsk'});if(events.length){holder.append(node('p',events[0].date===today?'По афише на сегодняшнюю дату:':'Ближайшая дата из нашей афиши:'));holder.append(eventCard(events[0]));}else holder.append(node('p','Актуальное расписание выступлений для этой группы пока не подключено.','muted'));holder.append(node('p','Показываем место выступления по афише. Фактическое местоположение участников не известно.','muted'));checked(holder,p.tour_checked_at);return;}
if(bandSection==='members'){holder.append(node('h2','Состав'));if(p.members_note)holder.append(node('p',p.members_note,'muted'));if(p.members?.length){for(const member of p.members){const row=node('div',undefined,'band-row');row.append(node('div',member.name));if(member.role)row.append(node('div',member.role,'muted'));holder.append(row);}}else holder.append(node('p','Подтверждённый список участников пока не добавлен.','muted'));checked(holder,p.members_checked_at||p.reference_checked_at);source(holder,p.members_source||p.reference_url,'Источник состава ↗');return;}
const links=node('div',undefined,'band-links');for(const [title,note,key]of [['Новости','Материалы об исполнителе','news'],['Концерты','Объявленные даты и места выступлений','tour'],['Альбомы','Дискография и участники записи','albums'],['Состав','Музыканты, инструменты и периоды','members'],['Сетлисты','Программы состоявшихся концертов','setlists']])links.append(sectionLink(title,note,key));holder.append(links);if(events.length){const upcoming=node('div',undefined,'fact');upcoming.append(node('small','Ближайшее объявленное выступление'),node('div',eventDate(events[0])+' · '+events[0].city));holder.append(upcoming);}const m=music[band.id];if(m?.data?.description)holder.append(node('p',m.data.description,'section-note'));if(m?.error)holder.append(node('p',m.error,'section-note'),button('Повторить загрузку справки',()=>loadGroupData(band,true)));else if(m?.loading)holder.append(node('p','Загружаем справочные данные…','loading-note'));holder.append(node('h2','Об исполнителе'));if(facts.isPerson)holder.append(button('Возраст, проекты и история музыканта',()=>openPerson(facts.qid)));for(const [label,value] of [['Откуда',p.origin],['Жанры',p.genres],['Годы активности',p.years_active],['Инструменты',p.instruments]])if(value){const row=node('div',undefined,'band-row');row.append(node('div',label,'muted'),node('div',value));holder.append(row);}if(facts.formed)holder.append(node('div','Дата основания в Wikidata: '+facts.formed.text,'fact'));if(p.about)holder.append(node('p',p.about));if(!p.reference_url&&!p.about&&!facts.source_url&&!m?.loading)holder.append(node('p','Справка пока не подключена. Новости этой группы доступны в соседнем разделе.','muted'));checked(holder,p.reference_checked_at);source(holder,p.website,'Сайт группы ↗');source(holder,p.musicbrainz_url,'MusicBrainz · дискография и связи ↗');source(holder,p.bandcamp_url,'Bandcamp · релизы исполнителя ↗');source(holder,p.reference_url,'Справочник ↗');source(holder,facts.source_url,'Wikidata ↗');if(ma.source_url){const block=node('details');block.append(node('summary','Metal Archives · дополнительная справка'));for(const [label,value]of [['Страна',ma.origin],['Город',ma.location],['Основана',ma.formed],['Жанры',ma.genre],['Годы активности',ma.years_active]])if(value)block.append(node('div',label+': '+musicalText(value),'fact'));if(ma.members?.length){block.append(node('h2','Состав по Metal Archives'));for(const member of ma.members)block.append(node('div',member.name+' · '+musicalText(member.role),'fact'));}source(block,ma.discography_url,'Дискография на Metal Archives ↗');checked(block,ma.checked_at);holder.append(block);}source(holder,ma.source_url||p.metal_archives_url||'https://www.metal-archives.com/search?searchString='+encodeURIComponent(band.name)+'&type=band_name','Metal Archives · группа и дискография ↗');if(facts.source_url)musicNote(holder);}

function toggleBlocked(id){const before={blocked:[...prefs.blocked],favorites:[...prefs.favorites]};prefs.blocked=prefs.blocked.includes(id)?prefs.blocked.filter(x=>x!==id):[...prefs.blocked,id];if(prefs.blocked.includes(id))prefs.favorites=prefs.favorites.filter(x=>x!==id);persist();renderBrowse();toast(prefs.blocked.includes(id)?'Новости исполнителя скрыты':'Исполнитель возвращён в ленту',()=>{prefs.blocked=before.blocked;prefs.favorites=before.favorites;persist();renderBrowse();});}
function blockButton(b){const el=button(prefs.blocked.includes(b.id)?'Показать':'Скрыть',()=>{registerBand(b);toggleBlocked(b.id);},'blocked');el.setAttribute('aria-label',(prefs.blocked.includes(b.id)?'Показывать новости: ':'Скрыть новости: ')+b.name);el.setAttribute('aria-pressed',String(prefs.blocked.includes(b.id)));return el;}
function bandRow(b){const row=node('div',undefined,'band-row');const title=button(b.name,()=>openBand(b),'band-title');if(b.description)title.append(node('small',b.description));if(prefs.blocked.includes(b.id))title.append(node('small','Скрыт из ленты','hidden-state'));row.append(title,star(b),blockButton(b));return row;}
function favoriteTile(b){const tile=node('div',undefined,'favorite-tile');const initials=b.name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();const open=button('',()=>openBand(b),'favorite-open');open.append(node('span',initials,'band-monogram'),node('strong',b.name));const available=selectArticles(articles,{band:b});const unread=available.filter(a=>!prefs.read.includes(a.id)).length;open.append(node('small',unread?unread+' новых':available.length+' новостей',unread?'band-new':'muted'));tile.append(open,star(b));return tile;}
function renderFavorites(){const el=$('groupShelf');for(const b of allBands().filter(b=>isFavorite(b.id)))el.append(bandRow(b));el.append(button('Выбрать из каталога',()=>setView('bands')),button('Найти другую группу',()=>setView('discover')));const hidden=allBands().filter(b=>prefs.blocked.includes(b.id));if(hidden.length){const d=node('details');d.append(node('summary','Скрытые исполнители · '+hidden.length));for(const b of hidden)d.append(bandRow(b));el.append(d);}}
function renderDiscovery(){ $('resultCount').textContent='Выберите точного исполнителя из результатов';$('list').append(button('Найти исполнителя',searchRemote,'search-action'));if(!query.trim()){$('list').append(node('p','Введите название группы или имя музыканта.','section-note'));return;}const local=allBands().filter(b=>norm(b.name).includes(norm(query)));for(const b of local)$('list').append(bandRow(b));}
async function searchRemote(){const token=++lookupToken,text=query.trim();if(text.length<2){$('resultCount').textContent='Введи хотя бы два символа';return;}$('resultCount').textContent='Ищем исполнителя…';try{const results=await window.MusicData.search(text);if(token!==lookupToken||view!=='discover'||query.trim()!==text)return;$('list').replaceChildren();$('resultCount').textContent='Найдено: '+results.length+' · выбери точное совпадение';for(const r of results){const local=allBands().find(b=>norm(b.name)===norm(r.name));const b=local?{...local,qid:r.qid,description:r.description}:r;const row=bandRow(b);row.children[0].addEventListener('click',()=>{if(!allBands().some(x=>x.id===b.id)){prefs.custom.push(b);persist();}else if(local&&!local.qid){local.qid=b.qid;} });$('list').append(row);}if(!results.length)$('list').append(node('p','Музыкальных совпадений не найдено. Попробуй оригинальное название.','section-note'));}catch(e){if(token===lookupToken&&view==='discover'){$('resultCount').textContent='Поиск сейчас недоступен';$('list').append(node('p','Источник не ответил. Попробуй ещё раз.', 'section-note'),button('Повторить',searchRemote));}}}
async function loadExtraReference(b){if(references[b.id]?.albums?.length||!window.MusicData?.extra)return;try{const p=await window.MusicData.extra(b,profileFor(b));references[b.id]=p;try{localStorage.setItem('metal-news.references.v1',JSON.stringify(references));}catch(e){}if(view==='band'&&band?.id===b.id)renderBrowse();}catch(e){}}
async function loadGroupData(b,retry=false){if(!window.MusicData)return;const previous=music[b.id];if(!retry&&(previous?.data||previous?.loading))return;music[b.id]={loading:true};if(view==='band'&&band?.id===b.id)renderBrowse();try{const data=await window.MusicData.group(b,profileFor(b));music[b.id]={data};const saved=prefs.custom.find(x=>x.id===b.id);if(saved){saved.aliases=[...new Set([saved.name,...Object.values(data.entity.labels||{}).map(x=>x.value)])];persist();}if(view==='band'&&band?.id===b.id)renderBrowse();}catch(e){music[b.id]={error:e.message||'Справочный источник недоступен.'};if(view==='band'&&band?.id===b.id)renderBrowse();}}
function musicNote(holder){holder.append(node('p','Справочные базы могут содержать пропуски и устаревшие записи. Совпадение Википедии и Wikidata не считается независимым подтверждением.','section-note'));}
function ageWord(age){return age%100>=11&&age%100<=14?'лет':age%10===1?'год':[2,3,4].includes(age%10)?'года':'лет';}
function musicalText(s){return String(s||'').replace(/lead and backing vocals/gi,'ведущий и бэк-вокал').replace(/backing vocals/gi,'бэк-вокал').replace(/lead vocals/gi,'ведущий вокал').replace(/bass guitar/gi,'бас-гитара').replace(/guitars?/gi,'гитара').replace(/keyboards?/gi,'клавишные').replace(/drums/gi,'ударные').replace(/percussion/gi,'перкуссия').replace(/vocals/gi,'вокал').replace(/piano/gi,'фортепиано').replace(/voice/gi,'вокал').replace(/soprano saxophone/gi,'сопрано-саксофон').replace(/saxophone/gi,'саксофон').replace(/assistant engineer/gi,'ассистент звукорежиссёра').replace(/engineer/gi,'звукорежиссёр').replace(/producer/gi,'продюсер').replace(/mixing/gi,'сведение').replace(/mastering/gi,'мастеринг').replace(/art direction/gi,'художественное оформление').replace(/continuum/gi,'континуум').replace(/occasional/gi,'иногда').replace(/synthesizers?/gi,'синтезатор').replace(/harmonica/gi,'губная гармоника').replace(/bass/gi,'бас').replace(/present/gi,'настоящее время').replace(/died/gi,'умер').replace(/guest/gi,'гость');}
function memberRow(member,official){const role=official?.role||member.role;const b=button('',()=>openPerson(member.id),'member-card');b.append(node('strong',member.name));if(role)b.append(node('small',musicalText(role)));if(official?.text)b.append(node('small',musicalText(official.text.replace(official.name,'').replace(/^[\s–—-]+/,''))));else{if(!role)b.append(node('small','Роль в группе не указана в источнике'));b.append(node('small','В группе: '+window.MusicData.span(member.begin,member.end)));}if(!role&&!official?.text&&member.instruments)b.append(node('small','Инструменты музыканта: '+musicalText(member.instruments)));if(member.birth)b.append(node('small',(member.death?'Годы жизни: ':'Родился: ')+member.birth.text+(member.death?' → '+member.death.text:'')+(member.age!==null?' · '+member.age+' '+ageWord(member.age)+(member.death?' на момент смерти':''):'')));return b;}
function renderMusicSection(holder,p){const state=music[band.id],data=state?.data;
if(bandSection==='setlists'){holder.append(node('h2','Концертные сетлисты'));const sets=p.setlist_analysis;if(sets?.shows?.length){holder.append(node('p','Сравнение проверенных сольных концертов. Фестивали не включены.','section-note'));if(sets.tour)holder.append(node('h2',sets.tour));for(const row of sets.songs||[])holder.append(node('div',row.name+' · '+row.count+'/'+sets.shows.length+(row.count===sets.shows.length?' · на всех концертах выборки':' · меняется'),'fact'));for(const show of newestFirst(sets.shows,'date'))source(holder,show.url,show.date+' · '+show.venue);}else{holder.append(node('p','Проверенных сетлистов в нашей базе пока нет. Программы отдельных концертов доступны у источника.','section-note'));source(holder,'https://www.setlist.fm/search?query='+encodeURIComponent(band.name),'Открыть setlist.fm ↗');}return;}
if(bandSection==='albums'){holder.append(node('h2','Альбомы'));if(p.albums?.length){renderReferenceAlbums(holder,p);return;}if(!data){musicStatus(holder,state);return;}const kinds=node('div',undefined,'filters');for(const [key,label] of [['studio','Студийные'],['live','Концертные'],['compilation','Сборники']]){const tab=button(label,()=>{albumKind=key;renderBrowse();});tab.setAttribute('aria-pressed',String(key===albumKind));kinds.append(tab);}holder.append(kinds);const a=state.albumLists?.[albumKind];if(a){holder.append(node('p','Список из дискографии Википедии по типу издания. Он может быть неполным; кредиты записи показываются в карточке альбома.','section-note'));if(!a.length)holder.append(node('p','Источник пока не содержит альбомов этого исполнителя.','section-note'));for(const album of newestFirst(a,'date')){const row=button('',()=>openAlbum(album.id),'album-row');row.append(node('strong',album.name),node('small',album.date?.slice(0,4)||'Год не указан'));holder.append(row);}source(holder,data.wikiSource,'Дискография исполнителя в Википедии ↗');}else if(state.albumErrors?.[albumKind]){holder.append(node('p','Каталог альбомов не загрузился.','section-note'),button('Повторить',()=>loadAlbums(band,true)));}else{holder.append(node('p','Загружаем альбомы…','loading-note'));loadAlbums(band);}return;}
holder.append(node('h2','Участники группы'));if(p.members?.length&&!data?.members?.length&&!data?.wikiMembers?.length){for(const m of p.members){const row=node('div',undefined,'member-card');row.append(node('strong',m.name),node('small',musicalText(m.role||'')));holder.append(row);}source(holder,p.members_source||p.musicbrainz_url||p.reference_url,'Источник состава ↗');checked(holder,p.reference_checked_at);return;}const official=p.members||[];if(!data){if(official.length){for(const m of official){const row=node('div',undefined,'member-card');row.append(node('strong',m.name),node('small',m.role||'Инструмент не указан'),node('small','Период участия и возраст пока не загружены'));holder.append(row);}source(holder,p.members_source||p.reference_url,'Источник состава ↗');}musicStatus(holder,state);return;}
const wiki=data.wikiMembers||[];const matching=m=>official.find(o=>norm(o.name)===norm(m.name));const currentNames=new Set(official.map(o=>norm(o.name)));const active=[...new Map(data.members.filter(m=>currentNames.has(norm(m.name))).sort((a,b)=>Number(!!b.end)-Number(!!a.end)).map(m=>[norm(m.name),m])).values()],former=data.members.filter(m=>m.end&&!currentNames.has(norm(m.name))),uncertain=data.members.filter(m=>!m.end&&!currentNames.has(norm(m.name)));
if(active.length){holder.append(node('p','Участники из опубликованного состава. Роли: '+sourceLabel(p.members_source||p.reference_url)+'. Периоды и даты рождения: Wikidata.','section-note'));for(const m of active)holder.append(memberRow(m,{...wiki.find(w=>norm(w.name)===norm(m.name)),...matching(m)}));}
for(const o of official.filter(o=>!data.members.some(m=>norm(m.name)===norm(o.name)))){const w=wiki.find(w=>norm(w.name)===norm(o.name));const row=w?button('',()=>openPersonTitle(w.title),'member-card'):node('div',undefined,'member-card');row.append(node('strong',o.name),node('small',o.role|| (w?musicalText(w.text.replace(w.name,'').replace(/^[\s–—-]+/,'')):'Инструмент не указан')));if(!w)row.append(node('small','В справочнике нет периода участия'));holder.append(row);}
if(former.length){const d=node('details');d.append(node('summary','Предыдущие участники · '+former.length));for(const m of former)d.append(memberRow(m,wiki.find(w=>norm(w.name)===norm(m.name))));holder.append(d);}
if(uncertain.length){const d=node('details');d.append(node('summary','Участие без подтверждённой даты окончания · '+uncertain.length));for(const m of uncertain)d.append(memberRow(m,wiki.find(w=>norm(w.name)===norm(m.name))));holder.append(d);}
const extra=wiki.filter(w=>!data.members.some(m=>norm(m.name)===norm(w.name))&&!official.some(o=>norm(o.name)===norm(w.name)));if(extra.length){const d=node('details');d.append(node('summary','Участники и периоды из Википедии · '+extra.length));for(const w of extra){const row=button('',()=>openPersonTitle(w.title),'member-card');row.append(node('strong',w.name),node('small',musicalText(w.text.replace(w.name,'').replace(/^[\s–—-]+/,''))),node('small',w.kind==='former'?'Бывший участник':w.kind==='current'?'Указан в опубликованном составе':'Статус требует уточнения'));d.append(row);}holder.append(d);source(holder,data.wikiHistorySource||data.wikiSource,'Роли и история состава в Википедии ↗');}
if(!data.members.length&&!official.length)holder.append(node('p','В источнике нет участников. Это не означает, что состав отсутствует.','section-note'));
if(p.members_note)holder.append(node('p',p.members_note,'section-note'));musicNote(holder);checked(holder,data.checked_at);source(holder,p.members_source||p.reference_url,'Источник опубликованного состава ↗');source(holder,data.source_url,'Периоды участия и даты рождения ↗');if(wiki.length)source(holder,data.wikiSource,'Роли и периоды из Википедии ↗');}
function musicStatus(holder,state){holder.append(node('p',state?.error||'Загружаем справочные данные…','loading-note'));if(state?.error)holder.append(button('Повторить',()=>loadGroupData(band,true)));}
async function loadAlbums(b,retry=false){const state=music[b.id],kind=albumKind;if(!state?.data)return;state.albumLists||={};state.albumLoading||={};state.albumErrors||={};if(!retry&&(state.albumLoading[kind]||state.albumLists[kind]))return;state.albumLoading[kind]=true;state.albumErrors[kind]=false;try{state.albumLists[kind]=await window.MusicData.albums(state.data.qid,kind);}catch(e){state.albumErrors[kind]=true;}finally{state.albumLoading[kind]=false;if(view==='band'&&band?.id===b.id&&bandSection==='albums'&&albumKind===kind)renderBrowse();}}
async function openPerson(qid){if(detail)detailStack.push(detail);detail={kind:'person',loading:true};renderBrowse();scrollTop();const pending=detail;try{pending.data=await window.MusicData.person(qid);}catch(e){pending.error=e.message;}pending.loading=false;if(detail===pending)renderBrowse();}
async function openPersonTitle(title){if(detail)detailStack.push(detail);detail={kind:'person',loading:true};renderBrowse();scrollTop();const pending=detail;try{pending.data=await window.MusicData.personByTitle(title);}catch(e){pending.error=e.message;}pending.loading=false;if(detail===pending)renderBrowse();}
async function openAlbum(qid){if(detail)detailStack.push(detail);detail={kind:'album',loading:true};renderBrowse();scrollTop();const pending=detail;try{pending.data=qid.startsWith('wiki:')?await window.MusicData.albumByTitle(qid.slice(5)):await window.MusicData.album(qid);}catch(e){pending.error=e.message;}pending.loading=false;if(detail===pending)renderBrowse();}
function creditText(text){const parts=text.split(/\s+[–—-]\s+/);return parts.length>1?parts.shift()+' — '+musicalText(parts.join(' — ')):text;}
function renderDetail(holder){holder.append(button(detailStack.length?'‹ Назад':'‹ Назад к группе',()=>{detail=detailStack.pop()||null;renderBrowse();scrollTop();}));if(detail.loading){holder.append(node('p','Загружаем карточку…','loading-note'));return;}if(detail.error){holder.append(node('p',detail.error,'section-note'));return;}const d=detail.data;holder.append(node('div',detail.kind==='person'?'Музыкант':'Альбом','detail-head'),node('h1',d.name));if(d.description)holder.append(node('p',d.description,'section-note'));
if(detail.kind==='person'){if(d.birth)holder.append(node('div','Дата рождения: '+d.birth.text,'fact'));if(d.death)holder.append(node('div','Дата смерти: '+d.death.text,'fact'));if(d.age!==null)holder.append(node('div',(d.death?'Возраст на момент смерти: ':'Возраст: ')+d.age+' '+ageWord(d.age),'fact'));if(d.instruments)holder.append(node('div','Инструменты: '+musicalText(d.instruments),'fact'));holder.append(node('h2','Участие в проектах'));for(const project of d.projects){const row=button('',()=>{const b=allBands().find(b=>norm(b.name)===norm(project.name))||{id:'wd:'+project.qid,qid:project.qid,name:project.name};if(!allBands().some(x=>x.id===b.id)){prefs.custom.push(b);persist();}openBand(b);},'album-row');row.append(node('strong',project.name),node('small',(project.begin||'Начало не указано')+' → '+(project.end||'Окончание не указано')));holder.append(row);}if(!d.projects.length)holder.append(node('p','В источнике нет истории участия в проектах.','section-note'));if(d.projectsError)holder.append(node('p','Часть связей с группами не загрузилась.','section-note'));holder.append(button('Альбомы с личным кредитом исполнителя',async()=>{const pending=detail;try{const rows=await window.MusicData.albums(d.qid,'credit');if(detail!==pending)return;const block=node('div');block.append(node('p','Только прямой кредит в базе. Участие в группе не доказывает участие в записи каждого её альбома.','section-note'));for(const a of newestFirst(rows,'date'))block.append(button(a.name+' · '+a.date.slice(0,4),()=>openAlbum(a.id),'album-row'));if(!rows.length)block.append(node('p','Прямые альбомные кредиты в базе не найдены.','section-note'));holder.append(block);}catch(e){if(detail===pending)holder.append(node('p','Не удалось загрузить альбомы.','section-note'));}}));
}else{if(d.date)holder.append(node('div','Дата выпуска: '+d.date.text,'fact'));holder.append(node('h2','Трек-лист'));if(d.tracks.length){const list=node('ol');for(const t of d.tracks)list.append(node('li',t.title+(t.duration&&t.duration!==t.title?' · '+t.duration:'')));holder.append(list);}else holder.append(node('p',d.detailsError?'Источник трек-листа не загрузился.':'Трек-лист в подключённом источнике не найден.','section-note'));holder.append(node('h2','Участники записи и кредиты'));for(const credit of d.credits)holder.append(credit.title?button(creditText(credit.text),()=>openPersonTitle(credit.title),'album-row'):node('div',creditText(credit.text),'fact'));if(!d.credits.length)holder.append(node('p','Кредиты записи не найдены. Состав группы не подставляется вместо участников записи.','section-note'));source(holder,d.wiki_url,'Трек-лист и кредиты в Википедии ↗');}musicNote(holder);source(holder,d.source_url,'Справочная карточка ↗');}


function stopSeenTracking(){seenObserver?.disconnect();seenObserver=null;visibleHeadlines.clear();for(const timer of seenTimers.values())clearTimeout(timer);seenTimers.clear();}
function markSeen(id){if(prefs.read.includes(id))return;prefs.read.push(id);persist();const card=[...document.querySelectorAll('[data-article-id]')].find(c=>c.dataset.articleId===id);if(card){card.classList.remove('is-unread');card.classList.add('is-read');const label=card.querySelector('.read-state');if(label)label.textContent='Просмотрено';}const count=selectArticles(articles,{view:prefs.settings.feedMode}).filter(a=>!prefs.read.includes(a.id)).length;window.MetalNewsPWA?.updateBadge(count);if(['all','mine','saved'].includes(view))$('resultCount').textContent=$('resultCount').textContent.replace(/непросмотренных: \d+/,'непросмотренных: '+count);}
function headlineVisible(el){if(settingsOpen||notificationView||current||document.visibilityState==='hidden'||!el.isConnected)return false;const r=el.getBoundingClientRect?.();if(!r||r.height<=0)return false;const height=window.innerHeight||document.documentElement.clientHeight;return Math.max(0,Math.min(r.bottom,height-85)-Math.max(r.top,0))>=r.height*.7;}
function queueSeen(){if(!hasScrolled||settingsOpen||current||notificationView)return;const rows=seenObserver?[...visibleHeadlines]:[...document.querySelectorAll('.card.is-unread .headline')];for(const el of rows){const id=el.closest('[data-article-id]')?.dataset.articleId;if(!id||prefs.read.includes(id))continue;if(!headlineVisible(el)){if(seenTimers.has(id)){clearTimeout(seenTimers.get(id));seenTimers.delete(id);}continue;}if(seenTimers.has(id))continue;seenTimers.set(id,setTimeout(()=>{seenTimers.delete(id);if(headlineVisible(el))markSeen(id);},1200));}}
function startSeenTracking(){if(typeof window.IntersectionObserver==='function'){seenObserver=new window.IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting&&entry.intersectionRatio>=.7)visibleHeadlines.add(entry.target);else{visibleHeadlines.delete(entry.target);const id=entry.target.closest('[data-article-id]')?.dataset.articleId;if(seenTimers.has(id)){clearTimeout(seenTimers.get(id));seenTimers.delete(id);}}}queueSeen();},{threshold:[0,.7,1],rootMargin:'0px 0px -85px 0px'});for(const el of document.querySelectorAll('.card.is-unread .headline'))seenObserver.observe(el);}queueSeen();}
function renderReferenceAlbums(holder,p){if(p.albums.every(a=>a.kind==='release'))albumKind='release';holder.append(node('p','Дискография из дополнительного источника.','section-note'));const tabs=node('div',undefined,'filters');for(const [k,label]of [['release','Релизы'],['studio','Студийные'],['live','Концертные'],['compilation','Сборники'],['ep','EP и синглы']]){const b=button(label,()=>{albumKind=k;renderBrowse();});b.setAttribute('aria-pressed',String(k===albumKind));tabs.append(b);}holder.append(tabs);const rows=p.albums.filter(a=>(a.kind||'studio')===albumKind);for(const a of newestFirst(rows,'date')){const row=node('div',undefined,'album-row');row.append(node('strong',a.name),node('small',a.date||''));source(row,a.source_url,'Релиз ↗');holder.append(row);}if(!rows.length)holder.append(node('p','В этом источнике нет изданий выбранного типа.','section-note'));source(holder,p.musicbrainz_url||p.bandcamp_url,'Источник дискографии ↗');}
function renderConcerts(){$('resultCount').textContent='Ближайшие события';const events=upcomingEvents({events:concerts});for(const e of events){const card=node('article',undefined,'concert-card');const date=node('div',undefined,'concert-date');date.append(node('strong',e.date.slice(8)),node('small',new Date(e.date+'T12:00:00').toLocaleDateString('ru-RU',{month:'short'})));const body=node('div');body.append(node('h2',e.title),node('p',[e.venue,e.time].filter(Boolean).join(' · '),'muted'));source(body,e.source_url,'Афиша и билеты ↗');card.append(date,body);$('list').append(card);}if(!events.length)empty('Новых подтверждённых дат пока нет.');const sources=node('details');sources.append(node('summary','Афиши города'));for(const [label,url]of [['Подземка · МТС Live','https://live.mts.ru/novosibirsk/venues/concert-hall/loft-park-podzemka'],['Рок · Яндекс Афиша','https://afisha.yandex.ru/novosibirsk/concert?rubric=rock'],['Подземка · объявления площадки','https://t.me/PodzemkaOfficial']])source(sources,url,label+' ↗');$('list').append(sources,node('p','Даты взяты из афиш. Перед покупкой проверьте время и возможные изменения у организатора.','section-note'));}
const NOTICE_KEY='metal-news.notifications.v1';let notices=[];try{notices=JSON.parse(localStorage.getItem(NOTICE_KEY)||'[]');if(!Array.isArray(notices))notices=[];}catch(e){}
function saveNotices(){try{localStorage.setItem(NOTICE_KEY,JSON.stringify(notices.slice(0,350)));}catch(e){}const b=$('notificationsBtn');if(b){const n=notices.filter(x=>!x.seen).length;b.dataset.count=n?String(n>99?'99+':n):'';b.setAttribute('aria-label','Уведомления'+(n?' · '+n+' новых':''));}}
function notificationEvents(){const rows=[...concerts];for(const [id,p]of Object.entries(profiles))for(const e of p.events||[]){const name=allBands().find(b=>b.id===id)?.name||p.name||id;rows.push({...e,id:'tour:'+id+':'+e.date+':'+e.city+':'+(e.venue||''),bandId:id,title:name+' · '+e.city});}return upcomingEvents({events:rows});}
function recordNotifications(){const known=new Set(notices.map(x=>x.id));const added=[];for(const a of articles)if(!a.translation_pending&&!known.has('news:'+a.id))added.push({id:'news:'+a.id,target:a.id,kind:'news',title:a.title,date:a.published,seen:false});for(const e of notificationEvents())if(!known.has('event:'+e.id))added.push({id:'event:'+e.id,target:e.id,kind:'event',bandId:e.bandId,title:e.title,date:e.date,seen:false});notices=[...added,...notices].slice(0,350);saveNotices();}
function openNotifications(){if(settingsOpen)closeSettings();stopSeenTracking();notificationView=true;current=null;showBrowse();$('viewTitle').textContent='Уведомления';$('viewIntro').textContent='Все новые новости и события';for(const id of ['feedModes','search','addBand','configureFeed','bandTabs','bandHero','bandInfo'])$(id).classList.add('hidden');$('list').replaceChildren();$('resultCount').textContent='Новых: '+notices.filter(x=>!x.seen).length;$('list').append(button('Отметить всё просмотренным',()=>{for(const n of notices)n.seen=true;saveNotices();openNotifications();},'pwa-action'));window.MetalNewsPWA?.appendSettings($('list'));for(const n of notices){const row=button('',()=>{n.seen=true;saveNotices();notificationView=false;if(n.kind==='news'){const a=allArticles().find(a=>a.id===n.target);if(a)openArticle(a);else{setView('all');toast('Материал уже вышел из текущего архива');}}else if(n.bandId){const b=allBands().find(b=>b.id===n.bandId);if(b)openBand(b);else setView('concerts');}else setView('concerts');},'notification-row'+(n.seen?'':' is-new'));row.append(node('small',n.kind==='news'?'Новость':'Концерт'),node('strong',n.title),node('small',new Date(n.date).toLocaleDateString('ru-RU')));$('list').append(row);}if(!notices.length)empty('Здесь появятся новые новости и события.');scrollTop();}
const noticeButton=button('',openNotifications,'notifications-button');noticeButton.id='notificationsBtn';noticeButton.innerHTML='<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>';document.querySelector('.top')?.insertBefore?.(noticeButton,$('closeBtn'));saveNotices();

