const ARTICLE_CACHE_KEY='metal-news.articles.v1';
try{concerts=JSON.parse($('concertsSeed')?.textContent||'{}').events||[];references=JSON.parse($('referencesSeed')?.textContent||'{}').profiles||{};}catch(e){}try{references={...references,...JSON.parse(localStorage.getItem('metal-news.references.v1')||'{}')};}catch(e){}try{metalArchives=JSON.parse($('metalArchivesSeed')?.textContent||'{}').profiles||{};}catch(e){}let loadedCatalog=false,loadedProfiles=false;try{catalog=JSON.parse($('artistsSeed').textContent||'{}').artists||[];window.MusicData?.seed(JSON.parse($('musicSeed').textContent||'{}'));}catch(e){}try{profiles=JSON.parse($('profilesSeed').textContent||'{}').profiles||{};}catch(e){}
function restoreArticleCache(){try{let cached=null;try{cached=JSON.parse(localStorage.getItem(ARTICLE_CACHE_KEY)||'null');}catch(e){}const seed=JSON.parse($('articlesSeed').textContent||'null');if(Array.isArray(seed?.articles)&&seed.articles.length&&(!Array.isArray(cached?.articles)||Number(seed.generated_at||0)>Number(cached.cachedAt||0))){cached={...seed,cachedAt:Number(seed.generated_at)||Date.now()};try{localStorage.setItem(ARTICLE_CACHE_KEY,JSON.stringify(cached));}catch(e){}}if(!Array.isArray(cached?.articles))return false;articles=cached.articles.filter(a=>a&&a.id).sort((a,b)=>new Date(b.published)-new Date(a.published));if(!articles.length)return false;const id=qs.get('id');try{localStorage.setItem(ARTICLE_CACHE_KEY,JSON.stringify({articles:cached.articles,cachedAt:cached.cachedAt||Date.now()}));}catch(e){}catalog=[...new Map([...catalog,...articles.flatMap(a=>a.artists||[])].map(a=>[a.id,a])).values()];$('status').classList.add('hidden');$('app').classList.remove('hidden');recordNotifications();renderBrowse();const target=id&&articles.find(a=>String(a.id)===id);if(target){openArticle(target,false);linkHandled=true;}else if(qs.get('band')){const b=allBands().find(b=>b.id===qs.get('band'));if(b)openBand(b);}return true;}catch(e){return false;}}
async function loadOptionalData(){const tasks=[(async()=>{try{const r=await fetch('concerts.json',{cache:'no-store'});if(r.ok){const data=await r.json();if(Array.isArray(data.events))concerts=data.events;}}catch(e){}})(),(async()=>{try{const r=await fetch('reference_sources.json',{cache:'no-cache'});if(r.ok)references={...references,...((await r.json()).profiles||{})};}catch(e){}})()];if(!loadedCatalog){loadedCatalog=true;tasks.push((async()=>{try{const c=await fetch('artists.json',{cache:'no-cache'});if(c.ok)catalog=(await c.json()).artists||[];}catch(e){}if(!catalog.length)catalog=[...new Map(articles.flatMap(a=>a.artists||[]).map(a=>[a.id,a])).values()];})());}if(!loadedProfiles){loadedProfiles=true;tasks.push((async()=>{try{const r=await fetch('artist_profiles.json?t='+Date.now(),{cache:'no-store'});if(r.ok)profiles=(await r.json()).profiles||{};}catch(e){}try{const seed=await fetch('music_cache.json');if(seed.ok&&window.MusicData)window.MusicData.seed(await seed.json());}catch(e){}})());}tasks.push((async()=>{try{const r=await fetch('metal_archives.json',{cache:'no-cache'});if(r.ok)metalArchives=(await r.json()).profiles||{};}catch(e){}})());await Promise.all(tasks);}
let refreshTimer=null,loadingFeed=false;
function scheduleRefresh(delay=60000){if(refreshTimer)clearTimeout(refreshTimer);refreshTimer=setTimeout(load,delay);}
async function load(){if(loadingFeed)return;if(refreshTimer)clearTimeout(refreshTimer);loadingFeed=true;tries++;try{const controller=typeof AbortController==='function'?new AbortController():null;const timeout=controller?setTimeout(()=>controller.abort(),12000):null;let r;try{r=await fetch('articles.json?t='+Date.now(),{cache:'no-store',...(controller?{signal:controller.signal}:{})});}finally{if(timeout)clearTimeout(timeout);}if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();if(!Array.isArray(data.articles))throw Error('Invalid news response');articles=newestFirst(data.articles.filter(a=>a&&a.id));try{localStorage.setItem(ARTICLE_CACHE_KEY,JSON.stringify({articles:data.articles||[],cachedAt:Date.now()}));}catch(e){}const id=qs.get('id');if(id&&!linkHandled&&!articles.some(a=>String(a.id)===id))throw Error('Article not published');if(!catalog.length)catalog=[...new Map(articles.flatMap(a=>a.artists||[]).map(a=>[a.id,a])).values()];$('status').classList.add('hidden');$('app').classList.remove('hidden');if(!notificationView)renderBrowse();if(id&&!linkHandled){openArticle(articles.find(a=>String(a.id)===id),false);linkHandled=true;}else if(!linkHandled&&qs.get('band')){const b=allBands().find(b=>b.id===qs.get('band'));if(b){openBand(b);linkHandled=true;}}recordNotifications();void loadOptionalData().then(()=>{recordNotifications();if(!current&&!notificationView)renderBrowse();});tries=0;scheduleRefresh();return;}catch(e){console.log(e);}finally{loadingFeed=false;}if(tries<60){if(!$('app').classList.contains('hidden')){scheduleRefresh(30000);return;}$('statusText').textContent=qs.get('id')?'Статья публикуется. Ещё несколько секунд…':'Не удалось загрузить ленту. Повторяю…';scheduleRefresh(3000);}else{$('statusText').textContent='Не удалось загрузить материал. Проверь соединение и попробуй снова.';document.querySelector('.spinner').style.display='none';$('status').append(button('Повторить',()=>{tries=0;load();}));}}
